import { readFileSync } from 'node:fs'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
const mode = args[0]
let workers = 0
if (mode === 'waves' || mode === 'explain') {
  if (args.length !== 1) fail(USAGE)
} else if (mode === 'pack') {
  if (args.length !== 2) fail(USAGE)
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail(USAGE)

let input = ''
try { input = readFileSync(0, 'utf8') } catch { input = '' }
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const costs = new Map()
const depSets = new Map()
const depUses = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 4 - 1 + 0 && w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (costs.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    costs.set(w[1], Number(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    if (!depSets.has(w[1])) depSets.set(w[1], new Set())
    for (const d of w.slice(1)) depUses.push(d)
    for (const d of w.slice(2)) depSets.get(w[1]).add(d)
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
for (const d of depUses) if (!costs.has(d)) fail(`error: unknown task ${d}`)

const names = [...costs.keys()].sort()
const deps = new Map(names.map((x) => [x, [...(depSets.get(x) || [])].sort()]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of deps.get(u)) {
      if (state.get(v) === 1) {
        const c = stack.slice(stack.indexOf(v)).concat(v)
        fail('error: cycle: ' + c.join(' -> '), 3)
      }
      if (!state.has(v)) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const x of names) if (!state.has(x)) visit(x)
}

const start = new Map(), finish = new Map(), depth = new Map()
const calc = (u) => {
  if (finish.has(u)) return
  let s = 0, d = 0
  for (const v of deps.get(u)) {
    calc(v)
    s = Math.max(s, finish.get(v))
    d = Math.max(d, depth.get(v) + 1)
  }
  start.set(u, s); finish.set(u, s + costs.get(u)); depth.set(u, d)
}
names.forEach(calc)
const total = names.reduce((m, x) => Math.max(m, finish.get(x)), 0)
const out = []

if (mode === 'waves') {
  const ws = []
  for (const x of names) (ws[depth.get(x)] ||= []).push(x)
  ws.forEach((l, k) => out.push(`wave ${k}: ${l.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const x of names) out.push(`${x} start=${start.get(x)} finish=${finish.get(x)} depth=${depth.get(x)}`)
  out.push(`total ${total}`)
} else {
  const prio = new Map()
  const dependents = new Map(names.map((x) => [x, []]))
  for (const x of names) for (const d of deps.get(x)) dependents.get(d).push(x)
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0
    for (const v of dependents.get(u)) m = Math.max(m, pr(v))
    prio.set(u, m + costs.get(u))
    return prio.get(u)
  }
  names.forEach(pr)
  const order = [...names].sort((a, b) => prio.get(b) - prio.get(a) || (a < b ? -1 : 1))
  const done = new Map()
  const freeAt = new Array(workers).fill(0)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0, remaining = names.length
  while (remaining > 0) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      const task = order.find((x) => !done.has(x) && deps.get(x).every((d) => done.has(d) && done.get(d) <= t))
      if (task === undefined) break
      done.set(task, t + costs.get(task))
      freeAt[wi] = t + costs.get(task)
      runs[wi].push(`${task}@${t}-${t + costs.get(task)}`)
      remaining--
    }
    if (remaining === 0) break
    t = Math.min(...freeAt.filter((f) => f > t))
  }
  runs.forEach((r, i) => out.push(`worker ${i}:` + r.map((s) => ' ' + s).join('')))
  out.push(`makespan ${total}`)
}
process.stdout.write(out.join('\n') + '\n')
EOF
