  for (const x of names) out.push(`${x} start=${start.get(x)} finish=${finish.get(x)} depth=${depth.get(x)}`)
  out.push(`total ${total}`)
} else {
  const prio = new Map()
  const dependents = new Map(names.map((x) => [x, []]))
  for (const x of names) for (const d of deps.get(x)) dependents.get(d).push(x)
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0
    for (const v of dependents.get(u)) m = Math.max(m, pr(v))
    prio.set(u, m + costs.get(u))
    return prio.get(u)
  }
  names.forEach(pr)
  const order = [...names].sort((a, b) => prio.get(b) - prio.get(a) || (a < b ? -1 : 1))
  const done = new Map()
  const freeAt = new Array(workers).fill(0)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0, remaining = names.length
  while (remaining > 0) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      const task = order.find((x) => !done.has(x) && deps.get(x).every((d) => done.has(d) && done.get(d) <= t))
      if (task === undefined) break
      done.set(task, t + costs.get(task))
      freeAt[wi] = t + costs.get(task)
      runs[wi].push(`${task}@${t}-${t + costs.get(task)}`)
      remaining--
    }
    if (remaining === 0) break
    t = Math.min(...freeAt.filter((f) => f > t))
  }
  runs.forEach((r, i) => out.push(`worker ${i}:` + r.map((s) => ' ' + s).join('')))
  out.push(`makespan ${total}`)
}
process.stdout.write(out.join('\n') + '\n')
